 ('eb29be42-6c0f-4421-91da-9a20f06dfef3'::uuid,'Master of Laws (LLM)','master-of-laws-llm-gimpa','Law','LLM','Postgraduate','2 years','https://gimpa.edu.gh/admissions/'),
 ('eb29be42-6c0f-4421-91da-9a20f06dfef3'::uuid,'Master of Project Management','master-of-project-management-gimpa','Project Management','Masters','Postgraduate','2 years','https://gimpa.edu.gh/admissions/'),
 ('eb29be42-6c0f-4421-91da-9a20f06dfef3'::uuid,'Master of Science in Digital Forensics and Cybersecurity','master-of-science-in-digital-forensics-and-cybersecurity-gimpa','Digital Forensics and Cybersecurity','MSc','Postgraduate','2 years','https://gimpa.edu.gh/admissions/')
), clean AS (
 SELECT DISTINCT ON (university_id, lower(regexp_replace(name,'[^a-zA-Z0-9]','','g')))
  university_id,name,slug,field,qualification,degree_type,duration,source_url
 FROM incoming
 ORDER BY university_id, lower(regexp_replace(name,'[^a-zA-Z0-9]','','g'))
)
INSERT INTO public.programmes
 (university_id,name,slug,field,qualification,degree_type,duration,programme_url,source_url,
  primary_source_url,source_urls,source_tier,verification_status,verified,needs_review,
  verification_method,verification_notes,notes,field_sources)
SELECT c.university_id,c.name,c.slug,c.field,c.qualification,c.degree_type,c.duration,c.source_url,c.source_url,
 c.source_url,ARRAY[c.source_url],'official_institution_catalogue',
 'source_linked_needs_individual_review',false,true,'Official institution programme list',
 'Programme title and award label copied from an official institution programme list; current offer and full details still need an individual review.',
 'Imported from an official institutional catalogue. Not verified; do not treat as confirmed current admission availability until reviewed.',
 jsonb_build_object('name',c.source_url,'qualification',c.source_url,'duration',c.source_url,'institution',c.source_url)
FROM clean c
WHERE NOT EXISTS (
 SELECT 1 FROM public.programmes existing
 WHERE existing.university_id=c.university_id
 AND lower(regexp_replace(existing.name,'[^a-zA-Z0-9]','','g')) =
     lower(regexp_replace(c.name,'[^a-zA-Z0-9]','','g'))
)
ON CONFLICT DO NOTHING;
